324	    /**
325	     * Counts of clients and projects, and the total still owed in each currency (what is left to pay
326	     * on sent invoices that are not yet fully paid; a currency with written-off invoices is listed even when nothing is owed), plus how many of those sent invoices are past their due date and
327	     * what is overdue on them (in total and split by how many days overdue each invoice is), what is outstanding as one grand total in the home currency (see {@link #inHome}), and the top clients ranked by what they owe.
328	     */
329	    @Transactional(readOnly = true)
330	    public DashboardResponse summary() {
331	        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
332	        Map<String, BigDecimal> owed = new TreeMap<>(Currency.ORDER);
333	        // A currency whose debts were written off stays listed, showing nothing owed, so the write-off is visible.
334	        clients.findAllById(invoices.sumAmountByStatusInPerClient(List.of(InvoiceStatus.WRITTEN_OFF)).stream()
335	                .map(InvoiceRepository.ClientTotal::getClientId).toList())
336	                .forEach(c -> owed.put(c.getCurrency(), BigDecimal.ZERO));
337	        owed.putAll(clientService.outstandingByCurrency());
338	        List<DashboardResponse.CurrencyTotal> outstanding = owed.entrySet().stream()
339	                .map(e -> new DashboardResponse.CurrencyTotal(e.getKey(), e.getValue().setScale(2, RoundingMode.HALF_UP)))
340	                .toList();
341	        LocalDate today = LocalDate.now(clock);
342	        long overdue = invoices.countByStatusInAndDueDateBefore(owing, today);
343	        String home = settings.homeCurrency();
344	        BigDecimal outstandingHome = sum(inHome(invoices.findByStatusInWithClient(owing), home, today, false));
345	        Map<Invoice, BigDecimal> overdueInHome = inHome(invoices.findByStatusInAndDueDateBefore(owing, today), home, today, true);
346	        BigDecimal overdueAmount = sum(overdueInHome);
347	        DashboardResponse.OverdueBuckets overdueBuckets = buckets(overdueInHome, today);
348	        List<DashboardResponse.TopClient> top = clientService.topByOutstanding(TOP_CLIENTS).stream()
349	                .map(c -> new DashboardResponse.TopClient(c.id(), c.name(), c.currency(), c.outstanding()))
