359	    private static DashboardResponse.OverdueBuckets buckets(Map<Invoice, BigDecimal> overdueInHome, LocalDate today) {
360	        BigDecimal upTo30 = BigDecimal.ZERO;
361	        BigDecimal days31To60 = BigDecimal.ZERO;
362	        BigDecimal days60Plus = BigDecimal.ZERO;
363	        for (Map.Entry<Invoice, BigDecimal> e : overdueInHome.entrySet()) {
364	            long days = ChronoUnit.DAYS.between(e.getKey().getDueDate(), today);
365	            if (days > 60) {
366	                days60Plus = days60Plus.add(e.getValue());
367	            } else if (days > 30) {
368	                days31To60 = days31To60.add(e.getValue());
369	            } else {
370	                upTo30 = upTo30.add(e.getValue());
371	            }
372	        }
373	        return new DashboardResponse.OverdueBuckets(upTo30.setScale(2, RoundingMode.HALF_UP),
374	                days31To60.setScale(2, RoundingMode.HALF_UP), days60Plus.setScale(2, RoundingMode.HALF_UP));
375	    }
