381	    /**
382	     * What is left to pay on each of the invoices, in the home currency, with the late fee and the interest on late
383	     * instalments each has built up by today when asked for (as for what is overdue). A foreign invoice converts at
384	     * the exchange rate from its issue date; one whose currency has no rate by then cannot be converted and is left out.
385	     */
386	    private Map<Invoice, BigDecimal> inHome(List<Invoice> found, String home, LocalDate today, boolean withCharges) {
387	        Map<Invoice, BigDecimal> amounts = new LinkedHashMap<>();
388	        if (found.isEmpty()) {
389	            return amounts;
390	        }
391	        List<Long> ids = found.stream().map(Invoice::getId).toList();
392	        Map<Long, BigDecimal> paid = payments.sumAmountByInvoiceIds(ids).stream()
393	                .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
394	                        PaymentRepository.InvoicePaidTotal::getPaid));
395	        Map<Long, BigDecimal> credited = creditNotes.sumAmountByInvoiceIds(ids).stream()
396	                .collect(Collectors.toMap(CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
397	                        CreditNoteRepository.InvoiceCreditedTotal::getCredited));
398	        Map<Long, List<Instalment>> scheduled = withCharges
399	                ? instalments.findByInvoiceIdIn(ids).stream().collect(Collectors.groupingBy(Instalment::getInvoiceId))
400	                : Map.of();
401	        for (Invoice invoice : found) {
402	            BigDecimal due = invoice.amountDue(paid.getOrDefault(invoice.getId(), BigDecimal.ZERO),
403	                    credited.getOrDefault(invoice.getId(), BigDecimal.ZERO));
404	            if (withCharges) {
405	                due = due.add(invoice.lateFee(invoice.getStatus(), today))
406	                        .add(interest(invoice, scheduled.getOrDefault(invoice.getId(), List.of()), today));
407	            }
408	            String currency = invoice.getProject().getClient().getCurrency();
409	            BigDecimal inHome = currency.equals(home) ? due
410	                    : fxRates.toHome(currency, invoice.getIssuedDate(), due).orElse(null);
411	            if (inHome != null) {
412	                amounts.put(invoice, inHome);
413	            }
414	        }
415	        return amounts;
416	    }
