419	    private static BigDecimal interest(Invoice invoice, List<Instalment> scheduled, LocalDate today) {
420	        BigDecimal total = BigDecimal.ZERO;
421	        for (Instalment instalment : scheduled) {
422	            if (instalment.isPaid()) {
