424	            }
425	            long daysLate = Math.max(0, ChronoUnit.DAYS.between(instalment.getDueDate(), today));
426	            total = total.add(invoice.getInstalmentInterestPerDay().multiply(BigDecimal.valueOf(daysLate))
427	                    .setScale(2, RoundingMode.HALF_UP));
428	        }
